import 'dart:async'; import 'package:slotbookingadmin/core/api/api_services.dart'; import '../models/booking_model.dart';
class BookingRemoteDatasource { final BookingApi _api=BookingApi(); BookingRemoteDatasource(); Stream<List<BookingModel>> watchAdminBookings(String adminId) async* { while(true){ yield (await _api.admin()).map(BookingModel.fromMap).toList(); await Future.delayed(const Duration(seconds:5)); } } Future<List<BookingModel>> getAdminBookingsForDateRange(String adminId,DateTime from,DateTime to) async=>(await _api.admin(from:from,to:to)).map(BookingModel.fromMap).toList(); Future<List<BookingModel>> getTodayBookings(String adminId) async{final n=DateTime.now();final s=DateTime(n.year,n.month,n.day);return getAdminBookingsForDateRange(adminId,s,s.add(const Duration(days:1)));}}
